const basis = get(ctx.subject.employer, 'pay_methods.night_differential_basis', 'WORKED');
const span = basis === 'CLOCK_SPAN';
const clocked = (d) => {
	const worked = get(d, 'intervals', []);
	if (worked.length === 0) return 0;
	const start = worked.reduce((a, i) => (i.start < a ? i.start : a), worked[0].start);
	const end = worked.reduce((a, i) => (i.end > a ? i.end : a), worked[0].end);
	return clock_window_minutes([{ start, end }], zone, ctx.lookup.night_from, ctx.lookup.night_to, ctx.as_of) / 60;
