	ctx.work.days.map((d) => {
		const night = Math.max(0, nightMinutes(d, 'intervals') - overtimeNight(d));
		const statute = (night * dayMultiple(d) + overtimeNight(d) * overtimeMultiple(d)) * ctx.lookup.multiplier;
		// Company method WHOLE_NIGHT: a shift whose own hours enter the night window pays the premium on eight hours at the day's multiple where that is more than the statute; overtime alone running into the night keeps the statute.
		if (basis === 'WHOLE_NIGHT' && night > 0) return Math.max(statute, 8 * dayMultiple(d) * ctx.lookup.multiplier);
		return span ? Math.max(statute, clocked(d) * ctx.lookup.multiplier) : statute;
	})
);
